    log_prob_w = extra.get("log_prob_w", batch.get("log_prob_w", None))
    log_prob_l = extra.get("log_prob_l", batch.get("log_prob_l", None))
    delta_z = extra.get("delta_z", batch.get("delta_z", None))
    weight = extra.get("weight", batch.get("weight", None))

    hp = extra.get("hyperparams", {})
    alpha = float(extra.get("alpha", hp.get("alpha", 1.0)))
    clamp_c = float(extra.get("clamp_c", hp.get("clamp_c", 3.0)))
    scale = float(extra.get("scale", hp.get("scale", 1.0)))
    w_min = float(extra.get("w_min", hp.get("w_min", 0.25)))
    w_max = float(extra.get("w_max", hp.get("w_max", 4.0)))
    eps = float(extra.get("eps", hp.get("eps", 1e-6)))

    if (log_prob_w is None) or (log_prob_l is None) or (delta_z is None):
        if weight is not None:
            return (weight * 0.0).mean()
        if delta_z is not None:
            return (delta_z * 0.0).mean()
        if log_prob_w is not None:
            return (log_prob_w * 0.0).mean()
        if log_prob_l is not None:
            return (log_prob_l * 0.0).mean()
        return ops.zeros(())

    # Base Bradley-Terry term (stable via logsigmoid)
    d = log_prob_w - log_prob_l
    base = -ops.logsigmoid(alpha * d)

    # Objective-sensitive bounded weighting
    c = ops.maximum(ops.ones(()) * clamp_c, ops.ones(()) * eps)
    g = ops.clamp(ops.zscore(delta_z), -c, c)
    w_obj = 1.0 + scale * (g / c)
    w_obj = ops.clamp(w_obj, w_min, w_max)

    per_pair = base * w_obj
    if weight is not None:
        per_pair = per_pair * weight

    return per_pair.mean()
